context_title:
ez mi?
field val: Int
field next: Ref

predicate List(this: Ref) {
  acc(this.val) && acc(this.next) &&
  (this.next != null ==> List(this.next))
}

predicate TokenEmbedding(this: Ref, size: Int) {
  acc(this.val) &&
  this.val >= 0 && this.val < size &&
  acc(this.next) &&
  (this.next != null ==> TokenEmbedding(this.next, size))
}

method tokenize_adaptive(text: Ref, vocab_size: Int) returns (tokens: Ref)
  requires text != null
  requires vocab_size > 0
  ensures tokens != null
  ensures TokenEmbedding(tokens, vocab_size)
{
  var current: Ref := null;
  var prev: Ref := null;

  current := new {
    val: 0,
    next: null
  }
  tokens := current

  assert current.val >= 0 && current.val < vocab_size;
  fold TokenEmbedding(current, vocab_size)
}

predicate SparseAttentionMask(this: Ref, seq_len: Int, sparsity: Int) {
  acc(this.val) &&
  this.val >= 0 && this.val <= seq_len &&
  sparsity >= 0 && sparsity <= 100 &&
  acc(this.next) &&
  (this.next != null ==> SparseAttentionMask(this.next, seq_len, sparsity))
}

method compute_sparse_mask(seq_len: Int, sparsity_ratio: Int) returns (mask: Ref)
  requires seq_len > 0
  requires sparsity_ratio >= 0 && sparsity_ratio <= 100
  ensures mask != null
  ensures SparseAttentionMask(mask, seq_len, sparsity_ratio)
{
  var k_sparse: Int := (seq_len * (100 - sparsity_ratio)) / 100;
  assert k_sparse > 0 && k_sparse <= seq_len;

  mask := new {
    val: k_sparse,
    next: null
  };
  fold SparseAttentionMask(mask, seq_len, sparsity_ratio)
}

predicate VocabState(this: Ref, current_size: Int, max_size: Int) {
  acc(this.val) &&
  this.val == current_size &&
  current_size >= 0 && current_size <= max_size &&
  max_size > 0
}

method add_token_runtime(vocab: Ref, current_size: Int, max_size: Int) returns (new_id: Int, new_vocab: Ref)
  requires vocab != null
  requires VocabState(vocab, current_size, max_size)
  requires current_size < max_size
  ensures new_vocab != null
  ensures VocabState(new_vocab, current_size + 1, max_size)
  ensures new_id == current_size
  ensures new_id >= 0 && new_id < max_size
{
  unfold VocabState(vocab, current_size, max_size);
  new_id := current_size;

  new_vocab := new {
    val: current_size + 1,
    next: null
  };
  fold VocabState(new_vocab, current_size + 1, max_size);

  assert new_id >= 0 && new_id < max_size;
}

predicate OptimizerState(this: Ref, lr: Int, mode: Int) {
  acc(this.val) &&
  lr > 0 &&
  mode >= 0 && mode <= 3 &&
  this.val == mode
}

method switch_optimizer_mode(opt: Ref, current_mode: Int, new_mode: Int, lr: Int) returns (new_opt: Ref)
  requires opt != null
  requires OptimizerState(opt, lr, current_mode)
  requires new_mode >= 0 && new_mode <= 3
  requires lr > 0
  ensures new_opt != null
  ensures OptimizerState(new_opt, lr, new_mode)
{
  unfold OptimizerState(opt, lr, current_mode);
  new_opt := new {
    val: new_mode,
    next: null
  };

  fold OptimizerState(new_opt, lr, new_mode);
}

predicate QuantumState(this: Ref, num_qubits: Int, depth: Int) {
  acc(this.val) &&
  num_qubits > 0 && num_qubits <= 127 &&
  depth > 0 &&
  this.val >= 0
}

method create_quantum_circuit(num_qubits: Int, depth: Int) returns (circuit: Ref)
  requires num_qubits > 0 && num_qubits <= 127
  requires depth > 0
  ensures circuit != null
  ensures QuantumState(circuit, num_qubits, depth)
{
  circuit := new {
    val: 0,
    next: null
  };
  fold QuantumState(circuit, num_qubits, depth);
}

predicate MemoryBound(this: Ref, allocated: Int, max_allowed: Int) {
  acc(this.val) &&
  this.val == allocated &&
  allocated >= 0 && allocated <= max_allowed &&
  max_allowed > 0
}

method allocate_memory(mem: Ref, current: Int, to_allocate: Int, max_allowed: Int) returns (new_mem: Ref)
  requires mem != null
  requires MemoryBound(mem, current, max_allowed)
  requires to_allocate > 0
  requires current + to_allocate <= max_allowed
  ensures new_mem != null
  ensures MemoryBound(new_mem, current + to_allocate, max_allowed)
{
  unfold MemoryBound(mem, current, max_allowed);
  new_mem := new {
    val: current + to_allocate,
    next: null
  };
  fold MemoryBound(new_mem, current + to_allocate, max_allowed);

  assert new_mem.val <= max_allowed;
}

predicate CelestialChart(chart: Ref)
{
  acc(chart.val, 1/2)
}

predicate SynastryMatrix(matrix: Ref, num_heads: Int)
{
  acc(matrix.val, 1/2) && num_heads == 1024
}

method apply_synastry_bias(scores: Ref, bias_matrix: Ref, num_heads: Int)
  requires acc(scores.val)
  requires SynastryMatrix(bias_matrix, num_heads)
  ensures acc(scores.val)
  ensures SynastryMatrix(bias_matrix, num_heads)
{
  assert forall i, j :: 0 <= i < num_heads && 0 <= j < num_heads ==> acc(bias_matrix.val[i][j]);
}

